#!/usr/bin/env python3
"""Make out/thumbnail.png (1280x720, < 2 MB) for a video project.

  thumb.py SLUG --text "4 GPUs, *ZERO* CLOUD" [--badge "132 tok/s"] [--bg FILE | --prompt "image prompt" | --frame N]
           [--variant B]                  writes out/thumbnail-B.png instead (for YouTube Test & Compare)

--text: 2-5 words, *word* = accent colour. --badge: one real number. Background (pick one):
  --bg assets/rig.jpg   your own photo or screenshot (best: real hardware, real terminal)
  --prompt "..."        generated by ComfyUI (Qwen-Image turbo, ~6 s warm; needs free VRAM)
  --frame N             a frame of the rendered video (scene N)
"""
import argparse, glob, json, os, pathlib, shutil, subprocess, sys, time

HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parents[2] / "lib"))
import content  # noqa: E402

COMFY = pathlib.Path.home() / ".config/comfyui"


def comfy_bg(prompt, dest):
    wf = COMFY / "workflows" / "qwen-image-2.1-turbo-t2i.api.json"
    before = set(glob.glob(str(pathlib.Path.home() / "ComfyUI/output/*.png")))
    full = (prompt + ", cinematic lighting, high contrast, dark background on the left third, no text, no letters,"
            " no watermark")
    r = subprocess.run([sys.executable, str(COMFY / "comfy_run.py"), str(wf), f"5.prompt={full}", "6.width=1344",
                        "6.height=768"], capture_output=True, text=True, timeout=900)
    new = sorted(set(glob.glob(str(pathlib.Path.home() / "ComfyUI/output/*.png"))) - before, key=os.path.getmtime)
    if r.returncode or not new:
        sys.exit("ERROR ComfyUI failed (free VRAM? `curl -s localhost:8080/unload`): " + (r.stdout + r.stderr)[-600:])
    shutil.copy(new[-1], dest)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("slug")
    ap.add_argument("--text", required=True)
    ap.add_argument("--badge", default="")
    g = ap.add_mutually_exclusive_group()
    g.add_argument("--bg")
    g.add_argument("--prompt")
    g.add_argument("--frame", type=int)
    ap.add_argument("--variant", default="")
    a = ap.parse_args()
    d = content.VIDEOS / a.slug
    (d / "assets").mkdir(parents=True, exist_ok=True)
    if len(a.text.replace("*", "").split()) > 6:
        print("WARN thumbnail text has more than 6 words - viewers read 3-4 at a glance")
    bg = None
    if a.bg:
        bg = a.bg
    elif a.prompt:
        bg = f"assets/thumb-bg{('-' + a.variant) if a.variant else ''}.png"
        t0 = time.time()
        comfy_bg(a.prompt, d / bg)
        print(f"background generated in {time.time()-t0:.0f} s")
    elif a.frame is not None:
        fr = json.loads((d / "plan.json").read_text())["items"]
        hit = [it["out"] for it in fr if it["s"] == a.frame]
        if not hit:
            sys.exit(f"ERROR no rendered frame for scene {a.frame} (run video.py render first)")
        bg = hit[-1]
    ch = content.channel()
    name = f"thumbnail{('-' + a.variant) if a.variant else ''}.png"
    out = d / "out" / name
    out.parent.mkdir(exist_ok=True)
    plan = {"page": "thumb.html", "width": 1280, "height": 720, "short": False, "brand": "", "dir": str(d), "force": True,
            "vars": {"--accent": ch["accent"]}, "scenes": [{"type": "thumb"}],
            "items": [{"s": 0, "beat": 0, "opts": {"text": a.text, "badge": a.badge, "bg": bg}, "out": str(out)}]}
    pf = d / "thumb-plan.json"
    pf.write_text(json.dumps(plan))
    r = subprocess.run(["node", str(HERE / "render.mjs"), str(pf)], capture_output=True, text=True)
    if r.returncode:
        sys.exit("ERROR render: " + r.stderr[-800:])
    size = out.stat().st_size / 1e6
    print(f"thumbnail: {out} ({size:.1f} MB{', TOO BIG for YouTube' if size > 2 else ''})")


if __name__ == "__main__":
    main()
